// prisma/seed.js (example)
const { PrismaClient } = require('@prisma/client');
const prisma = new PrismaClient();

async function main() {
  const user = await prisma.user.upsert({
    where: { email: 'admin@example.com' },
    update: {},
    create: {
      id: 'admin-user-1',
      name: 'Admin',
      email: 'admin@example.com',
    },
  });

  const posts = [
    { title: 'Getting Started with Next.js', slug: 'getting-started', content: '<p>Next.js is the React framework...</p>', published: true },
    { title: 'The Power of Prisma', slug: 'power-of-prisma', content: '<p>Prisma makes database access easy...</p>', published: true },
    { title: 'Draft Post', slug: 'draft-post', content: '<p>Not published yet</p>', published: false },
  ];

  for (const post of posts) {
    await prisma.post.upsert({
      where: { slug: post.slug },
      update: {},
      create: { ...post, authorId: user.id },
    });
  }
}

main()
  .catch(e => { console.error(e); process.exit(1); })
  .finally(async () => await prisma.$disconnect());

